import{_ as t,o,c as d,a4 as n}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"Où sont vos données","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"Où sont vos données","description":"Extrait de deploy/LISEZMOI.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"documentation/referent/ou-sont-vos-donnees.md","filePath":"documentation/referent/ou-sont-vos-donnees.md"}'),s={name:"documentation/referent/ou-sont-vos-donnees.md"};function r(a,e,c,i,u,l){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="où-sont-vos-données" tabindex="-1">Où sont vos données <a class="header-anchor" href="#où-sont-vos-données" aria-label="Permalink to &quot;Où sont vos données {#où-sont-vos-données}&quot;">​</a></h1><p>Tout ce qui doit survivre à une mise à jour ou à un redémarrage vit dans un volume nommé Docker, jamais dans le conteneur lui-même :</p><table tabindex="0"><thead><tr><th>Volume</th><th>Contenu</th></tr></thead><tbody><tr><td><code>donnees-postgres</code></td><td>La base de données : contenus, comptes, journaux applicatifs récents.</td></tr><tr><td><code>donnees-api</code></td><td>Fichiers liés à une personne (RGPD) et médiathèque — tout ce que <code>MEDIA_ROOT</code>/<code>PERSONAL_FILE_ROOT</code> désignent dans l&#39;image.</td></tr><tr><td><code>caddy-data</code></td><td>Certificats HTTPS obtenus auprès de Let&#39;s Encrypt.</td></tr><tr><td><code>sauvegardes/</code> (dossier, pas un volume)</td><td>Les sauvegardes nocturnes — voir ci-dessous.</td></tr><tr><td><code>copie-distante/</code> (dossier 700, pas un volume)</td><td>La configuration de la copie distante : mot de passe du dépôt, identifiants S3 ou clé SSH, hôte vérifié — <strong>des secrets</strong>, absents du <code>.env</code> et de toute sauvegarde. Voir <a href="/teuthis-cms-distribution/documentation/referent/copie-distante-chiffree#copie-distante-chiffrée">« Copie distante chiffrée »</a>.</td></tr><tr><td><code>cache-restic</code></td><td>Cache de la copie distante : se reconstruit, rien à sauvegarder.</td></tr><tr><td><code>donnees-clamav</code>, <code>donnees-ollama</code></td><td>Signatures antivirus, modèles IA locaux — seulement si ces profils sont actifs.</td></tr><tr><td><code>etat-ordonnanceur</code></td><td>Battement de l&#39;ordonnanceur, <strong>en mémoire</strong> (<code>tmpfs</code>) : rien à sauvegarder, vidé à chaque arrêt de la pile.</td></tr></tbody></table><p><code>docker volume ls</code> les liste, préfixés du nom du projet Compose : <code>teuthis</code> pour une installation guidée (fixé par <code>COMPOSE_PROJECT_NAME</code> dans <code>.env</code>), sinon le nom du dossier (<code>deploy</code>) ou celui passé à <code>-p</code>.</p>',4)])])}const v=t(s,[["render",r]]);export{m as __pageData,v as default};
